fn reverse_upto_k(s: &mut Vec<i32>, k: usize) {
    let mut left = 0;
    let mut right = k - 1;

    while left < right {
        // Swap the elements at the left and right indices
        s.swap(left, right);
        left += 1;
        right -= 1;
    }
}